BEGIN;
CREATE TABLE app.planned_work_revision(id uuid NOT NULL,tenant_id uuid NOT NULL,job_id uuid NOT NULL,command_id uuid NOT NULL,task_key text NOT NULL,revision integer NOT NULL CHECK(revision>0),plan_date date NOT NULL,predecessor_complete boolean,required_units integer NOT NULL CHECK(required_units>=0),landed_units integer NOT NULL CHECK(landed_units>=0),access_ready boolean,crew_ready boolean,labour_rate_pence bigint CHECK(labour_rate_pence BETWEEN 0 AND 1000000000000),uncertain_duration_hours integer CHECK(uncertain_duration_hours BETWEEN 0 AND 1000000),actor_ref text NOT NULL,subject_ref uuid NOT NULL,payload_hash char(64) NOT NULL,audit_event_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT transaction_timestamp(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,command_id),UNIQUE(tenant_id,job_id,task_key,revision),UNIQUE(tenant_id,job_id,id),FOREIGN KEY(tenant_id,job_id)REFERENCES app.job(tenant_id,id),FOREIGN KEY(tenant_id,audit_event_id)REFERENCES app.audit_event(tenant_id,id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE app.readiness_snapshot(id uuid NOT NULL,tenant_id uuid NOT NULL,job_id uuid NOT NULL,command_id uuid NOT NULL,planned_work_revision_id uuid NOT NULL,revision integer NOT NULL CHECK(revision>0),rule_revision text NOT NULL,source_facts_hash char(64) NOT NULL,adapter_revision text NOT NULL,adapter_reading_hash char(64) NOT NULL,scenario_now timestamptz NOT NULL,weather_observed_at timestamptz,weather_state varchar(10) NOT NULL CHECK(weather_state IN('true','false','unknown')),ready boolean NOT NULL,reasons jsonb NOT NULL,exposure_pence bigint CHECK(exposure_pence BETWEEN 0 AND 1000000000000),recovery_fee_pence bigint NOT NULL DEFAULT 0 CHECK(recovery_fee_pence=0),actor_ref text NOT NULL,subject_ref uuid NOT NULL,payload_hash char(64) NOT NULL,audit_event_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT transaction_timestamp(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,command_id),UNIQUE(tenant_id,job_id,planned_work_revision_id,revision),UNIQUE(tenant_id,job_id,id),FOREIGN KEY(tenant_id,job_id,planned_work_revision_id)REFERENCES app.planned_work_revision(tenant_id,job_id,id),FOREIGN KEY(tenant_id,audit_event_id)REFERENCES app.audit_event(tenant_id,id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE app.readiness_decision(id uuid NOT NULL,tenant_id uuid NOT NULL,job_id uuid NOT NULL,command_id uuid NOT NULL,snapshot_id uuid NOT NULL,revision integer NOT NULL CHECK(revision>0),decision_kind text NOT NULL CHECK(decision_kind='due_review'),rule_revision text NOT NULL,source_facts_hash char(64) NOT NULL,adapter_reading_hash char(64) NOT NULL,due_at timestamptz NOT NULL,actor_ref text NOT NULL,subject_ref uuid NOT NULL,payload_hash char(64) NOT NULL,audit_event_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT transaction_timestamp(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,command_id),UNIQUE(tenant_id,job_id,snapshot_id,revision),UNIQUE(tenant_id,job_id,id),FOREIGN KEY(tenant_id,job_id,snapshot_id)REFERENCES app.readiness_snapshot(tenant_id,job_id,id),FOREIGN KEY(tenant_id,audit_event_id)REFERENCES app.audit_event(tenant_id,id) DEFERRABLE INITIALLY DEFERRED);
DO $$ DECLARE n text;BEGIN FOREACH n IN ARRAY ARRAY['planned_work_revision','readiness_decision','readiness_snapshot'] LOOP EXECUTE format('ALTER TABLE app.%I OWNER TO jobguard_migration',n);EXECUTE format('ALTER TABLE app.%I ENABLE ROW LEVEL SECURITY',n);EXECUTE format('ALTER TABLE app.%I FORCE ROW LEVEL SECURITY',n);EXECUTE format('CREATE POLICY tenant_isolation ON app.%I FOR ALL TO jobguard_runtime,jobguard_migration USING(tenant_id=current_setting(''app.tenant_id'')::uuid) WITH CHECK(tenant_id=current_setting(''app.tenant_id'')::uuid)',n);EXECUTE format('GRANT SELECT,INSERT ON app.%I TO jobguard_runtime',n);EXECUTE format('REVOKE UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER ON app.%I FROM jobguard_runtime',n);END LOOP;END$$;
COMMIT;
